import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 67 Volcanoes","description":"学习 完成进行时与持续活动，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 67 Volcanoes","description":"学习 完成进行时与持续活动，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 完成进行时与持续活动，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 66 Sweet as honey!","link":"/life/english/new-concept/book-2/unit-03/lesson-066"},"next":{"text":"第二册：实践与进步 · Lesson 68 Persistent","link":"/life/english/new-concept/book-2/unit-03/lesson-068"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 66 Sweet as honey!","link":"/life/english/new-concept/book-2/unit-03/lesson-066"},"next":{"text":"第二册：实践与进步 · Lesson 68 Persistent","link":"/life/english/new-concept/book-2/unit-03/lesson-068"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-03/lesson-067.md","filePath":"life/english/new-concept/book-2/unit-03/lesson-067.md"}'),i={name:"life/english/new-concept/book-2/unit-03/lesson-067.md"};function s(r,e,l,h,c,d){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-lesson-67-volcanoes" tabindex="-1">第二册：实践与进步 · Lesson 67 Volcanoes <a class="header-anchor" href="#第二册-实践与进步-·-lesson-67-volcanoes" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 67 Volcanoes&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>研究火山需要记录持续监测与已经观测到的变化；练习能够证实的观察和预测。本课的语言观察是：have been monitoring 表持续工作；have recorded three changes 则是成果数量。观察资料可支持判断，但不等于精确预知每次喷发。完成学习后，请写一段科学观察简报，给出监测时段、一项发现和仍不确定的信息。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>volcano</td><td>/vɒlˈkeɪnəʊ/</td><td>n.</td><td>火山</td><td>an active volcano</td></tr><tr><td>eruption</td><td>/ɪˈrʌpʃən/</td><td>n.</td><td>喷发</td><td>a volcanic eruption</td></tr><tr><td>observe</td><td>/əbˈzɜːv/</td><td>v.</td><td>观察</td><td>observe carefully</td></tr><tr><td>scientist</td><td>/ˈsaɪəntɪst/</td><td>n.</td><td>科学家</td><td>a research scientist</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>keep a record of — 记录某事</li><li>show signs of — 显示出……的迹象</li></ul><h2 id="语法讲解-完成进行时与持续活动" tabindex="-1">语法讲解：完成进行时与持续活动 <a class="header-anchor" href="#语法讲解-完成进行时与持续活动" aria-label="Permalink to &quot;语法讲解：完成进行时与持续活动&quot;">​</a></h2><p>现在完成进行时由 have/has been 加 -ing 构成，强调从过去持续到现在或刚刚停止且影响仍可见的活动。现在完成时更容易突出完成的数量或结果，进行形式则突出过程和时长。状态动词通常不用进行形式。for 引出时长，since 引出起点；句中有一段时间并不自动要求完成进行时，还要判断动作性质与当前是否有关联。本课应用：have been monitoring 表持续工作；have recorded three changes 则是成果数量。观察资料可支持判断，但不等于精确预知每次喷发。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The scientists have been monitoring the volcano since March.</p></blockquote><p>科学家们自三月以来一直在监测这座火山。</p><p>have been monitoring 是完成进行时，since March 给起点；scientists 是复数主语。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>since three months 不合常用表达；用 for three months 或 since March。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>重读 since March 与 exact date，避免将“没有确切日期”读成“已有日期”。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The scientists have been monitoring the volcano since March. They have recorded a rise in ground temperature. The report does not give an exact eruption date.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一段科学观察简报，给出监测时段、一项发现和仍不确定的信息。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：have been monitoring 是完成进行时，since March 给起点；scientists 是复数主语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：since three months 不合常用表达；用 for three months 或 since March。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选 since/for：They have been observing it ___ March.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> since</p><p><strong>解析：</strong> March 是时间起点。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>报告有没有给出确切喷发日期？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> No.</p><p><strong>解析：</strong> 最后一句限制了可以得出的结论。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>用 for 改写 since three months ago。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> for three months</p><p><strong>解析：</strong> 前者起点距今三个月，后者直接表达持续时长。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：完成进行时与持续活动。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-066">上一课</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-068">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",s]]);export{u as __pageData,b as default};
